import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int limit1 = 1 << ((n / 2) + (n % 2));
        int limit2 = 1 << (n / 2);
        int[] b = new int[limit1];
        int index_b = 0;

        for (int i = 0; i < limit1; i++) {
            int total = 0;
            int mask = i;
            for (int j = 0; j < 20; j++) {
                if ((mask & 1) == 1) {
                    total += a[j];
                }
                mask >>= 1;
            }
            b[index_b++] = total % m;
        }

        Arrays.sort(b);
        int max_value = 0;

        for (int i = 0; i < limit2; i++) {
            int total = 0;
            int mask = i;
            for (int j = 0; j < 20; j++) {
                if ((mask & 1) == 1) {
                    total += a[(n / 2) + (n % 2) + j];
                }
                mask >>= 1;
            }
            total %= m;

            int index = Arrays.binarySearch(b, m - total - 1);
            if (index < 0) {
                index = -index - 1;
            }

            int candidate;
            if (index < b.length) {
                candidate = b[index];
                if (candidate > m - total - 1 && index - 1 >= 0) {
                    candidate = b[index - 1];
                }
            } else {
                candidate = b[b.length - 1];
            }

            max_value = Math.max(max_value, Math.max((total + candidate) % m, (total + b[b.length - 1]) % m));
        }

        System.out.println(max_value % m);
        sc.close();
    }
}
